local ThreadReelMaker = {}
local PRODUCTS = {
    simple_wood_thread_reel = { name = "Preprosta lesena nitna navijalka", woodCost = 2, time = 3, cost = 35, science = 12, happiness = 1, description = "Preprosta lesena nitna navijalka za shranjevanje niti." },
    iron_spindle_reel = { name = "Železnovretenčna navijalka", woodCost = 2, ironCost = 1, time = 5, cost = 100, science = 25, happiness = 1, prestige = 2, description = "Železnovretenčna navijalka za trgovce." },
    silver_trimmed_reel = { name = "Srebrnoobrobljena navijalka", woodCost = 2, silverCost = 1, ironCost = 1, time = 8, cost = 260, science = 38, happiness = 2, prestige = 6, description = "Srebrnoobrobljena navijalka za plemiče." },
    gold_trimmed_reel = { name = "Zlatookrasna navijalka", woodCost = 2, goldCost = 1, silverCost = 1, ironCost = 1, time = 12, cost = 620, science = 52, happiness = 3, prestige = 14, description = "Zlatookrasna navijalka za visoke plemiče." },
    jewel_set_reel = { name = "Draguljasta navijalka", woodCost = 2, goldCost = 1, silverCost = 1, ironCost = 1, jewelCost = 1, time = 16, cost = 1400, science = 68, happiness = 5, prestige = 27, description = "Navijalka z draguljem za visoko plemstvo." },
    royal_grand_reel = { name = "Kraljevski veliki navijalka", woodCost = 3, goldCost = 2, silverCost = 2, ironCost = 1, jewelCost = 2, pearlCost = 2, time = 23, cost = 3100, science = 88, happiness = 12, prestige = 58, description = "Velika kraljevska navijalka z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    reel_workshop = { name = "Navijalna delavnica", cost = { gold = 250, wood = 140, stone = 120 }, upkeep = 5, qualityBonus = 5 },
    textile_loft = { name = "Tekstilna podstrešje", cost = { gold = 920, wood = 280, stone = 240, silver = 6, iron = 6 }, upkeep = 21, qualityBonus = 18 },
    master_reel_atelier = { name = "Mojstrski navijalni atelje", cost = { gold = 2600, wood = 380, stone = 480, silver = 30, gold = 6 }, upkeep = 60, qualityBonus = 30 },
    royal_textile_palace = { name = "Kraljevska tekstilna palača", cost = { gold = 11000, wood = 580, stone = 760, gold = 70, jewel = 16 }, upkeep = 220, qualityBonus = 55, prestigeBonus = 50 },
}
ThreadReelMaker.woodStock = 16; ThreadReelMaker.ironStock = 10; ThreadReelMaker.silverStock = 6; ThreadReelMaker.goldStock = 6; ThreadReelMaker.jewelStock = 4; ThreadReelMaker.pearlStock = 4
ThreadReelMaker.productStock = {}; ThreadReelMaker.buildings = {}; ThreadReelMaker.maker = nil; ThreadReelMaker.activeMaking = {}; ThreadReelMaker.totalProducts = 0; ThreadReelMaker.dayTimer = 0
function ThreadReelMaker.init() ThreadReelMaker.woodStock=16; ThreadReelMaker.ironStock=10; ThreadReelMaker.silverStock=6; ThreadReelMaker.goldStock=6; ThreadReelMaker.jewelStock=4; ThreadReelMaker.pearlStock=4; ThreadReelMaker.productStock={}; ThreadReelMaker.buildings={}; ThreadReelMaker.maker=nil; ThreadReelMaker.activeMaking={}; ThreadReelMaker.totalProducts=0; ThreadReelMaker.dayTimer=0; print("[ThreadReelMaker] Royal Thread Reel Maker System initialized (6 products, 4 buildings)") end
function ThreadReelMaker.hireMaker(n,s) s=s or math.random(55,90); local c=530+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ThreadReelMaker.maker={name=n or ("Navijalkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Navijalkar najet: %s (spretnost: %d)",ThreadReelMaker.maker.name,s),"success") end; return true end
function ThreadReelMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ThreadReelMaker.build(id) local ok,e=ThreadReelMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ThreadReelMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ThreadReelMaker.getQualityBonus() local b=0; for _,bd in ipairs(ThreadReelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ThreadReelMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and ThreadReelMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and ThreadReelMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.silverCost and ThreadReelMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ThreadReelMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ThreadReelMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ThreadReelMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ThreadReelMaker.buildings==0 then return false,"Potrebna navijalna delavnica" end; if not ThreadReelMaker.maker then return false,"Potreben navijalkar" end; return true end
function ThreadReelMaker.make(pt,qty) qty=qty or 1; local ok,e=ThreadReelMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then ThreadReelMaker.woodStock=ThreadReelMaker.woodStock-d.woodCost*qty end; if d.ironCost then ThreadReelMaker.ironStock=ThreadReelMaker.ironStock-d.ironCost*qty end; if d.silverCost then ThreadReelMaker.silverStock=ThreadReelMaker.silverStock-d.silverCost*qty end; if d.goldCost then ThreadReelMaker.goldStock=ThreadReelMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ThreadReelMaker.jewelStock=ThreadReelMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ThreadReelMaker.pearlStock=ThreadReelMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ThreadReelMaker.maker then t=math.max(1,t-math.floor(ThreadReelMaker.maker.skill/14)) end; table.insert(ThreadReelMaker.activeMaking,{id="threadreel_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ThreadReelMaker.completeMaking(m) local q=1.0+(ThreadReelMaker.getQualityBonus()/100); if ThreadReelMaker.maker then q=q+(ThreadReelMaker.maker.skill/140) end; q=math.min(2.5,q); ThreadReelMaker.productStock[m.productType]=(ThreadReelMaker.productStock[m.productType] or 0)+m.quantity; ThreadReelMaker.totalProducts=ThreadReelMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ThreadReelMaker.maker then ThreadReelMaker.maker.itemsMade=ThreadReelMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ThreadReelMaker.maker.skill=math.min(100,ThreadReelMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Navijalka izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"threadreel.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function ThreadReelMaker.update(dt) if not _G.state then return end; ThreadReelMaker.dayTimer=ThreadReelMaker.dayTimer+dt; if ThreadReelMaker.dayTimer>=30 then ThreadReelMaker.dayTimer=0; for i=#ThreadReelMaker.activeMaking,1,-1 do local m=ThreadReelMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ThreadReelMaker.completeMaking(m); table.remove(ThreadReelMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ThreadReelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ThreadReelMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ThreadReelMaker.getStats() return {woodStock=ThreadReelMaker.woodStock,ironStock=ThreadReelMaker.ironStock,silverStock=ThreadReelMaker.silverStock,goldStock=ThreadReelMaker.goldStock,jewelStock=ThreadReelMaker.jewelStock,pearlStock=ThreadReelMaker.pearlStock,productStock=ThreadReelMaker.productStock,numBuildings=#ThreadReelMaker.buildings,hasMaker=ThreadReelMaker.maker~=nil,makerName=ThreadReelMaker.maker and ThreadReelMaker.maker.name or "—",makerSkill=ThreadReelMaker.maker and ThreadReelMaker.maker.skill or 0,activeMaking=#ThreadReelMaker.activeMaking,totalProducts=ThreadReelMaker.totalProducts} end
return ThreadReelMaker
